(async()=>{const out={},fonts=typeof document==='object'?document.fonts:self.fonts,run=async(n,f)=>{if(typeof document==='object')document.title=n;try{out[n]=await f()}catch(e){out[n]=e.name}};for(const [key,source]of [['local','local("Arial")'],['missing','local("mimic-no-such-font-98347")'],['fallback','local("mimic-no-such-font-98347"), local("Arial")'],['invalidURL','url("data:font/woff;base64,AA==")']])await run(key,async()=>{const f=new FontFace('Alias-'+key,source),before=f.status;fonts.add(f);const checkBefore=fonts.check('16px "Alias-'+key+'"'),p=f.load(),during=f.status;const result=await p.then(v=>[v===f,f.status],e=>[e.name,f.status]);const checkAfter=fonts.check('16px "Alias-'+key+'"'),loaded=await fonts.load('16px "Alias-'+key+'"').then(v=>v.map(x=>x===f),e=>e.name);fonts.delete(f);return [before,checkBefore,during,p===f.loaded,result,checkAfter,loaded]});await run('unrelated',async()=>{const f=new FontFace('OnlyThis','local("mimic-no-such-font-98347")');fonts.add(f);const a=fonts.check('16px OtherFamily'),b=await fonts.load('16px OtherFamily');fonts.delete(f);return [a,b.length,f.status]});await run('glyphSelection',async()=>{const f=new FontFace('Subset','local("Arial")',{unicodeRange:'U+41'});fonts.add(f);const a=[fonts.check('16px Subset','B'),fonts.check('16px Subset','A')],b=await fonts.load('16px Subset','B');fonts.delete(f);return [a,b.length,f.status]});if(typeof document==='object')document.title='done';return out})()
